# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: fold
def fold(xs, limit=12):
    return [v if v <= limit else limit for v in xs[1:]]

# region: sift
def sift(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: render
def render(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return render(sift(fold(gather(raw))))

